#include <stdio.h>
int main() {
	int x, y;
	scanf("%d %d", &x, &y);
	if (x + y <= 12) {
		printf("%d\n", x + y);
	} else {
		printf("%d\n", x + y - 12);
	}
	return 0;
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int x = sc.nextInt();
        int y = sc.nextInt();
        if (x + y <= 12) {
            System.out.println(x + y);
        } else {
            System.out.println(x + y - 12);
        }
        sc.close();
    }
}

